INSERT INTO "investment_plans" ("id", "name", "min_amount", "max_amount", "website_fee", "weekly_return_percent", "duration_weeks", "crowdfunding_limit", "lifetime_profit_sharing", "features", "active", "created_at", "updated_at") VALUES ('1', 'National Package', '100000', '490000', '20000', '1.75', '100', '1000000', '৫,০০০ থেকে ২০,০০০ টাকা / মাস', '["Branded Shopify Store and Product","Own Packaging","Paid Campaign Setup","Crowdfunding Opportunity up to 10 Lac","Weekly 1.75% for 100 weeks (24 Months)","Example: 1,20,000 Tk -> 1,750 Tk\/week = Total 1,75,000 Tk"]', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "investment_plans" ("id", "name", "min_amount", "max_amount", "website_fee", "weekly_return_percent", "duration_weeks", "crowdfunding_limit", "lifetime_profit_sharing", "features", "active", "created_at", "updated_at") VALUES ('2', 'International Package', '500000', NULL, '50000', '2', '100', '5000000', '২৫,০০০ থেকে ১,০০,০০০ টাকা / মাস', '["Dedicated Team for Project Management","Unlimited UGC Content","Crowdfunding Opportunity up to 50 Lac","Weekly 2% for 100 weeks (24 Months)","Example: 5,50,000 Tk -> 10,000 Tk\/week = Total 10,00,000 Tk"]', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "commission_types" ("id", "name", "code", "rate_description", "description", "active", "created_at", "updated_at") VALUES ('1', 'Spot Commission', 'spot', '10% on Investment', 'SBL এ আপনার রেফারেন্সে যত প্রজেক্ট ডেভেলপমেন্ট হবে তার বিনিয়োগকৃত অ্যামাউন্ট থেকে ১০% মার্কেটিং কমিশন।', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "commission_types" ("id", "name", "code", "rate_description", "description", "active", "created_at", "updated_at") VALUES ('2', 'Refer Return', 'refer_return', '0.25% per week for 100 weeks', 'আপনার রেফারেন্সের বিনিয়োগকৃত অ্যামাউন্টের উপর ০.২৫% করে প্রতি সপ্তাহে পাবেন ১০০ সপ্তাহ পর্যন্ত।', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "commission_types" ("id", "name", "code", "rate_description", "description", "active", "created_at", "updated_at") VALUES ('3', 'Pair Reward', 'pair_reward', '500 Tk/Pair (Daily max 100 PR = 50,000 Tk)', 'আপনার রেফারেন্স ও সেলস টিম গঠন করে প্রতিদিন সর্বোচ্চ ১০০ পেয়ার কমিশন। পেয়ারের কোনো নির্দিষ্ট লিমিট নেই।', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "commission_types" ("id", "name", "code", "rate_description", "description", "active", "created_at", "updated_at") VALUES ('4', 'Unity Development Commission (UDR)', 'udr', '5% across sales team', 'আপনার রেফারেন্স ও সেলস টিম গঠন করে অতিরিক্ত ৫% পর্যন্ত কমিশন পাবেন।', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
INSERT INTO "commission_types" ("id", "name", "code", "rate_description", "description", "active", "created_at", "updated_at") VALUES ('5', 'Rank Reward', 'rank_reward', 'Up to 40,00,000 Tk Cash Incentive', 'আপনার রেফারেন্সে সেলস টিম গঠন করে বিভিন্ন পদবী অর্জনের মাধ্যমে ৪০ লক্ষ টাকা পর্যন্ত পুরস্কার পাবেন।', '1', '2026-09-06 07:51:38', '2026-09-06 07:51:38');
