-- SBL Tools Cloudflare D1 Database Schema and Seed Data
PRAGMA foreign_keys = OFF;

DROP TABLE IF EXISTS "users";
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "phone" varchar, "designation" varchar, "status" varchar not null default 'active');


DROP TABLE IF EXISTS "password_reset_tokens";
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

DROP TABLE IF EXISTS "sessions";
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));


DROP TABLE IF EXISTS "cache";
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "cache_locks";
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "jobs";
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

DROP TABLE IF EXISTS "job_batches";
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));

DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

DROP TABLE IF EXISTS "lead_sources";
CREATE TABLE "lead_sources" ("id" integer primary key autoincrement not null, "name" varchar not null, "is_active" tinyint(1) not null default '1', "order" integer not null default '0', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "leads";
CREATE TABLE "leads" ("id" integer primary key autoincrement not null, "name" varchar not null, "mobile" varchar not null, "whatsapp" varchar, "email" varchar, "facebook_url" varchar, "location" varchar, "profession_or_business" varchar, "lead_source_id" integer not null, "lead_source_detail" varchar, "interest_types" text, "lead_tag" varchar, "stage" varchar not null default 'new', "temperature" varchar not null default 'cold', "score" integer not null default '0', "is_manual_score" tinyint(1) not null default '0', "budget_range" varchar, "decision_timeline" varchar, "owner_user_id" integer not null, "next_action_type" varchar, "next_action_at" datetime, "last_contact_at" datetime, "converted_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("lead_source_id") references "lead_sources"("id") on delete cascade, foreign key("owner_user_id") references "users"("id") on delete cascade);


DROP TABLE IF EXISTS "lead_interests";
CREATE TABLE "lead_interests" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "interest" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade);


DROP TABLE IF EXISTS "activities";
CREATE TABLE "activities" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "user_id" integer, "type" varchar not null, "title" varchar not null, "description" text, "metadata" text, "performed_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);


DROP TABLE IF EXISTS "tasks";
CREATE TABLE "tasks" ("id" integer primary key autoincrement not null, "title" varchar not null, "type" varchar not null, "related_lead_id" integer, "related_customer_id" integer, "related_member_id" integer, "user_id" integer not null, "due_at" datetime not null, "priority" varchar not null default 'Medium', "status" varchar not null default 'Pending', "notes" text, "completed_at" datetime, "outcome" varchar, "next_action" varchar, "next_action_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("related_lead_id") references "leads"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);


DROP TABLE IF EXISTS "presentations";
CREATE TABLE "presentations" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "user_id" integer not null, "date_time" datetime not null, "type" varchar not null, "topic" varchar, "interest_focus" varchar, "questions" text, "objections" text, "outcome" varchar, "next_follow_up_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);


DROP TABLE IF EXISTS "campaigns";
CREATE TABLE "campaigns" ("id" integer primary key autoincrement not null, "name" varchar not null, "platform" varchar, "start_date" date, "end_date" date, "budget" numeric, "status" varchar not null default 'Active', "notes" text, "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "content_items";
CREATE TABLE "content_items" ("id" integer primary key autoincrement not null, "campaign_id" integer, "user_id" integer not null, "title" varchar not null, "platform" varchar not null, "content_type" varchar, "topic" varchar, "caption" text, "creative_path" varchar, "scheduled_at" datetime not null, "published_at" datetime, "status" varchar not null default 'Planned', "cta" varchar, "reach" integer, "engagement" integer, "inbox_count" integer, "leads_generated" integer, "conversions" integer, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("campaign_id") references "campaigns"("id") on delete set null, foreign key("user_id") references "users"("id") on delete cascade);


DROP TABLE IF EXISTS "daily_activity_logs";
CREATE TABLE "daily_activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer not null, "date" date not null, "calls" integer not null default '0', "messenger_contacts" integer not null default '0', "whatsapp_contacts" integer not null default '0', "new_leads" integer not null default '0', "follow_ups" integer not null default '0', "presentations" integer not null default '0', "meetings" integer not null default '0', "conversions" integer not null default '0', "product_sales_count" integer not null default '0', "received_income" numeric not null default '0', "note" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);

DROP TABLE IF EXISTS "ranks";
CREATE TABLE "ranks" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "order" integer not null default '1', "requirement_text" text not null, "incentive_amount" numeric, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "investment_plans";
CREATE TABLE "investment_plans" ("id" integer primary key autoincrement not null, "name" varchar not null, "min_amount" numeric not null, "max_amount" numeric, "website_fee" numeric not null default '0', "weekly_return_percent" numeric not null, "duration_weeks" integer not null default '100', "crowdfunding_limit" numeric, "lifetime_profit_sharing" varchar, "features" text, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "commission_types";
CREATE TABLE "commission_types" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar not null, "rate_description" varchar not null, "description" text, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "roles";
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" varchar, "is_system" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "permissions";
CREATE TABLE "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "module" varchar not null, "description" varchar, "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "role_user";
CREATE TABLE "role_user" ("id" integer primary key autoincrement not null, "user_id" integer not null, "role_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade);


DROP TABLE IF EXISTS "permission_role";
CREATE TABLE "permission_role" ("id" integer primary key autoincrement not null, "role_id" integer not null, "permission_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("role_id") references "roles"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade);


DROP TABLE IF EXISTS "permission_user";
CREATE TABLE "permission_user" ("id" integer primary key autoincrement not null, "user_id" integer not null, "permission_id" integer not null, "type" varchar not null default 'grant', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade);

DROP TABLE IF EXISTS "ecosystem_links";
CREATE TABLE "ecosystem_links" ("id" integer primary key autoincrement not null, "title" varchar not null, "url" varchar not null, "category" varchar not null default 'Official Portals', "badge" varchar, "description" text, "icon" varchar not null default '🌐', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "sbl_contacts";
CREATE TABLE "sbl_contacts" ("id" integer primary key autoincrement not null, "department" varchar not null, "contact_person" varchar, "phone" varchar not null, "whatsapp" varchar, "email" varchar, "available_hours" varchar not null default '10:00 AM - 08:00 PM', "description" text, "icon" varchar not null default '📞', "badge" varchar, "is_primary" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS "binary_nodes";
CREATE TABLE "binary_nodes" ("id" integer primary key autoincrement not null, "user_id" integer, "member_name" varchar not null, "member_code" varchar not null, "phone" varchar, "email" varchar, "parent_id" integer, "sponsor_id" integer, "position" varchar check ("position" in ('left', 'right')), "package_name" varchar not null default 'National 120k', "point_value" numeric not null default '100', "left_count" integer not null default '0', "right_count" integer not null default '0', "left_bv" numeric not null default '0', "right_bv" numeric not null default '0', "carry_left" numeric not null default '0', "carry_right" numeric not null default '0', "matched_pairs" integer not null default '0', "rank_name" varchar not null default 'Member', "avatar" varchar, "is_active" tinyint(1) not null default '1', "joined_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("parent_id") references "binary_nodes"("id") on delete set null, foreign key("sponsor_id") references "binary_nodes"("id") on delete set null);


PRAGMA foreign_keys = ON;
